#!/usr/bin/env bash
# @generated by rubio-standards. DO NOT EDIT: `copier update` replaces this whole file.
# Source: Rubio-Enterprises/standards, template/scripts/regenerate-lint-config.sh
# shellcheck source-path=SCRIPTDIR
# To change this, open a PR against the template; there is no per-repo override.
# regenerate-lint-config.sh — rebuild this repo's GENERATED lint configs from the
# org floor merged with its committed `*.local` sidecars.
#
# WHY THIS EXISTS:
# The generated configs (`ruff.toml`, `biome.jsonc`, `.yamllint`,
# `.markdownlint-cli2.jsonc`, `treefmt.toml`, `tombi.toml`) are floor ⊕ delta merges. The floor lives in the
# standards template, not in this repo, so refreshing one needs a render. The
# only way to do that used to be `copier update`, which diff-applies the ENTIRE
# template across the repo, runs migrations, and drags unrelated template drift
# into your branch — absurdly heavy for "I changed one rule in a .local file".
#
# This script runs the SAME recipe the org CI gate runs (`.github`'s
# `standards-gates.yml` lint-config check): resolve the standards channel, render the template into a
# scratch dir with this repo's answers and its committed `.local` sidecars
# seeded, let the `_tasks` merge hooks compose floor ⊕ delta, then copy back
# ONLY the config files. Nothing else in the repo is touched.
#
# Running the identical recipe as the gate is the point: "regenerated locally"
# and "passes the config drift check" are then the same computation. A
# hand-rolled lighter merge could diverge from the gate, which is the exact bug
# class this replaces.
#
# USAGE:
#   mise run lint-config        # regenerate in place
#   mise run lint-config -- --check   # exit 1 if anything is stale (no writes)
#
# Requires: copier + yq (both mise-pinned in this repo), git, and — only to read
# the `ring` property — gh. Without gh (or offline gh), the channel falls back to
# `stable`, exactly as the gate's own fail-safe does.

set -euo pipefail

# Drop every repo-scoped git variable before doing anything else. Git EXPORTS
# these to hook processes, and this script is one: the `lint-config` pre-commit
# hook runs it. copier clones the template with git into a temp dir, and those
# nested git invocations inherit the environment — so with `GIT_INDEX_FILE`
# still set, the template checkout is written into THIS repo's index instead of
# the clone's. The repo's index is replaced by the template's tree (302 entries
# where there were 79, 6 of them standards' own `.claude/skills/run-standards/`
# paths), and because copier deletes its temp clone the referenced blobs vanish
# with it, so the next commit dies on `error: invalid object … Error building
# trees` — which reads like repository corruption and is not. Reproduced and
# fixed 2026-09-02 after it blocked two commits on claude-workflows#116;
# recovery for an already-clobbered index is `git read-tree --reset HEAD`.
#
# Unsetting is safe here: every git/gh call this script (and every copier
# `_tasks` script beneath it) needs resolves from the working directory, which
# is the repo root by the check above. It is also the only correct scope — a
# tool invoked from a hook must not hand its own repo context to a nested
# checkout of a different repository.
unset GIT_INDEX_FILE GIT_DIR GIT_WORK_TREE GIT_COMMON_DIR \
  GIT_OBJECT_DIRECTORY GIT_ALTERNATE_OBJECT_DIRECTORIES GIT_PREFIX

CHECK_ONLY=0
if [[ "${1:-}" = "--check" ]]; then
  CHECK_ONLY=1
fi

if [[ ! -f .copier-answers.yml ]]; then
  echo "regenerate-lint-config: no .copier-answers.yml here; run from the repo root." >&2
  exit 1
fi

# The Pattern F configs. Each is written solely by its `merge-*.sh` hook, so
# whatever the render produces IS the canonical content. `biome.json` is absent
# by design: the rendered Biome target is `biome.jsonc` (strict JSON forbids the
# @generated banner comment, and a comment in `biome.json` makes Biome silently
# fall back to its own defaults).
CONFIGS=(ruff.toml biome.jsonc .yamllint .markdownlint-cli2.jsonc treefmt.toml tombi.toml)
SIDECARS=(ruff.toml.local biome.json.local .yamllint.local .markdownlint-cli2.jsonc.local treefmt.toml.local tombi.toml.local)

resolve_channel() {
  # Same rule as the gate: `ring == canary` -> canary, `ring == stable` ->
  # stable; unset or unreadable properties also default to stable. Never fail
  # here; a wrong-but-safe channel beats aborting a local regeneration.
  local slug ring
  if ! command -v gh >/dev/null 2>&1; then
    echo stable
    return 0
  fi
  slug="$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || true)"
  if [[ -z "${slug}" ]]; then
    echo stable
    return 0
  fi
  ring="$(gh api "repos/${slug}/properties/values" \
    --jq '.[] | select(.property_name=="ring") | .value' 2>/dev/null || true)"
  if [[ "${ring}" = "canary" ]]; then
    echo canary
  else
    echo stable
  fi
}

yq_bin() {
  if command -v yq >/dev/null 2>&1; then
    printf 'yq'
  elif command -v mise >/dev/null 2>&1; then
    printf 'mise exec -- yq'
  else
    echo "regenerate-lint-config: yq not found; run 'mise install' first." >&2
    exit 1
  fi
}

copier_bin() {
  if command -v copier >/dev/null 2>&1; then
    printf 'copier'
  elif command -v mise >/dev/null 2>&1; then
    printf 'mise exec -- copier'
  else
    echo "regenerate-lint-config: copier not found; run 'mise install' first." >&2
    exit 1
  fi
}

YQ="$(yq_bin)"
COPIER="$(copier_bin)"

SRC="$(${YQ} -r '._src_path' .copier-answers.yml)"
if [[ -z "${SRC}" ]] || [[ "${SRC}" = "null" ]]; then
  echo "regenerate-lint-config: .copier-answers.yml has no _src_path." >&2
  exit 1
fi

CHANNEL="$(resolve_channel)"
WORK="$(mktemp -d)"
trap 'rm -rf "${WORK}"' EXIT
RENDER_DIR="${WORK}/render"
mkdir -p "${RENDER_DIR}"

# Preserve knowledgebase locations, not their content, so the formatter merge
# sees the same ownership in a scratch render as in a real Copier update.
# Both template and consumer layouts keep this library beside the script.
# Single-file checks do not follow imports; the shared library is checked itself.
# shellcheck source=common/knowledgebase-paths.sh disable=SC1091
source "$(dirname "${BASH_SOURCE[0]}")/common/knowledgebase-paths.sh"
seed_knowledgebase_markers "${RENDER_DIR}"

# Strip copier's `_`-prefixed metadata so it only sees question answers (the gate
# does the same before its render).
${YQ} 'with_entries(select(.key | test("^_") | not))' .copier-answers.yml >"${WORK}/answers.yml"

# Seed the committed sidecars so the merge hooks compose floor ⊕ delta rather
# than floor-only. Without this the regenerated config would silently DROP every
# declared repo carve-out.
for sidecar in "${SIDECARS[@]}"; do
  if [[ -f "${sidecar}" ]]; then
    cp "${sidecar}" "${RENDER_DIR}/${sidecar}"
  fi
done

# Seed the committed GENERATED configs too — including the legacy `biome.json`
# name — so the template's divergence guards (migrate-ruff-detect-divergence.sh,
# migrate-biome-detect-divergence.sh) see the same destination state a real
# `copier update` sees, and reach the same verdict here as they do there.
#
# They must: a repo that owns a Pattern-D `biome.json` with no
# `biome.json.local` is UNCONVERTED, and the guard drops the floor fragment for
# it at render time, leaving the consumer's own config in charge. Rendering into
# a dir that held none of that made the guard see a greenfield destination, keep
# the fragment, and emit a floor `biome.jsonc` the repo does not (and must not)
# commit — reported as permanently STALE, with no commit able to satisfy it,
# since writing that file would produce a config `biome.json` then beats in
# biome's own resolution order. It bit exactly the unconverted repos that also
# carry some OTHER sidecar, because the hook's glob fires on any sidecar and
# then checks all applicable configs (claude-lsps#159, yaml-static-webpage-template#148,
# 2026-09-02); unconverted repos with no sidecar at all never fired it and so
# looked fine.
for cfg in "${CONFIGS[@]}" biome.json; do
  if [[ -f "${cfg}" ]]; then
    cp "${cfg}" "${RENDER_DIR}/${cfg}"
  fi
done

echo "regenerate-lint-config: rendering standards@${CHANNEL} from ${SRC}"
if ! ${COPIER} copy --vcs-ref="${CHANNEL}" --data-file "${WORK}/answers.yml" \
  --defaults --trust --quiet "${SRC}" "${RENDER_DIR}"; then
  echo "regenerate-lint-config: render failed (offline? bad channel?)." >&2
  echo "  Your committed configs are unchanged." >&2
  exit 1
fi

stale=0
changed=()
for cfg in "${CONFIGS[@]}"; do
  rendered="${RENDER_DIR}/${cfg}"
  # Not every config applies to every repo (ruff.toml only for has_python, and
  # so on). A config the render did not produce is not this repo's concern.
  [[ -f "${rendered}" ]] || continue

  if [[ -f "${cfg}" ]] && cmp -s "${cfg}" "${rendered}"; then
    continue
  fi

  stale=1
  changed+=("${cfg}")
  if [[ "${CHECK_ONLY}" -eq 0 ]]; then
    cp "${rendered}" "${cfg}"
  fi
done

if [[ "${stale}" -eq 0 ]]; then
  echo "regenerate-lint-config: every generated config is already current."
  exit 0
fi

if [[ "${CHECK_ONLY}" -eq 1 ]]; then
  echo "regenerate-lint-config: STALE generated config: ${changed[*]}" >&2
  echo "  These files do not match the standards floor ⊕ this repo's *.local sidecars." >&2
  echo "  Fix: mise run lint-config   (then commit the regenerated file)" >&2
  exit 1
fi

echo "regenerate-lint-config: regenerated ${changed[*]}"
echo "  Commit the regenerated file(s) alongside the .local change that caused it."
